# Build output grid based on checkerboard pattern in all 4 regions
def build_output():
    grid = [[0]*12 for _ in range(12)]

    # Top-left: rows 0-7, cols 0-6
    for r in range(8):
        for c in range(7):
            if (r+c) % 2 == 0:
                grid[r][c] = 4
            else:
                grid[r][c] = 0

    # Top-right: rows 0-7, cols 8-11
    for r in range(8):
        for c in range(4):
            if (r+c) % 2 == 0:
                grid[r][8+c] = 4
            else:
                grid[r][8+c] = 0

    # Bottom-left: rows 9-11, cols 0-6
    for r in range(3):
        for c in range(7):
            if (r+c) % 2 == 0:
                grid[9+r][c] = 4
            else:
                grid[9+r][c] = 0

    # Bottom-right: rows 9-11, cols 8-11
    for r in range(3):
        for c in range(4):
            if (r+c) % 2 == 0:
                grid[9+r][8+c] = 4
            else:
                grid[9+r][8+c] = 0

    return grid

output = build_output()
for row in output:
    print(' '.join(map(str, row)))

